  (SELECT count(*)::int FROM positions WHERE source = 'loadtest-synthetic-2569') AS loadtest_positions,
  (SELECT count(*)::int FROM companies WHERE visibility = 'public' AND (catalog_key IS NOT NULL OR NOT EXISTS (
